  1	package br.com.marealta;
  2	
  3	import br.com.marealta.messaging.Installation;
  4	import br.com.marealta.messaging.MessagePipeline;
  5	import br.com.marealta.messaging.MessageSink;
  6	import br.com.marealta.persistence.Database;
  7	import br.com.marealta.persistence.ReservationRepository;
  8	import br.com.marealta.persistence.RoomRepository;
  9	import br.com.marealta.persistence.StoredMessages;
 10	import br.com.marealta.web.Routes;
 11	import com.fasterxml.jackson.databind.ObjectMapper;
 12	import com.fasterxml.jackson.databind.SerializationFeature;
 13	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 14	import io.javalin.Javalin;
 15	import io.javalin.json.JavalinJackson;
 16	
 17	public final class Main {
 18	    private Main() {
 19	    }
 20	
 21	    public static void main(String[] args) {
 22	        Database database = new Database(required("DB_URL"), System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
 23	        database.initialize();
 24	
 25	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 26	        int port = System.getenv("PORT") == null ? 7070 : Integer.parseInt(System.getenv("PORT"));
 27	
 28	        createApp(database, testMode).start(port);
 29	    }
 30	
 31	    public static Javalin createApp(Database database, boolean testMode) {
 32	        StoredMessages storedMessages = new StoredMessages(database);
 33	        MessageSink outbox = MessagePipeline.assemble(storedMessages, Installation.mareAlta(), testMode);
 34	        RoomRepository rooms = new RoomRepository();
 35	        ReservationRepository reservations = new ReservationRepository();
 36	        ReservationService service = new ReservationService(database, rooms, reservations, outbox);
 37	        Reports reports = new Reports(database, rooms, reservations);
 38	
 39	        ObjectMapper mapper = new ObjectMapper().registerModule(new JavaTimeModule())
 40	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 41	        Javalin app = Javalin.create(config -> config.jsonMapper(new JavalinJackson(mapper, false)));
 42	        new Routes(service, storedMessages, reports, mapper).register(app);
 43	        return app;
 44	    }
 45	
 46	    private static String required(String name) {
 47	        String value = System.getenv(name);
 48	        if (value == null || value.isBlank()) {
 49	            throw new IllegalStateException("Environment variable " + name + " is required");
 50	        }
 51	        return value;
 52	    }
 53	}
 54	package br.com.marealta;
 55	
 56	import br.com.marealta.domain.DomainException;
 57	import br.com.marealta.domain.ErrorCode;
 58	import br.com.marealta.domain.Quote;
 59	import br.com.marealta.domain.RatePlan;
 60	import br.com.marealta.domain.Receipt;
 61	import br.com.marealta.domain.Reservation;
 62	import br.com.marealta.domain.ReservationStatus;
 63	import br.com.marealta.domain.Room;
 64	import br.com.marealta.domain.Money;
 65	import br.com.marealta.messaging.Message;
 66	import br.com.marealta.messaging.MessageSink;
 67	import br.com.marealta.persistence.Database;
 68	import br.com.marealta.persistence.ReservationRepository;
 69	import br.com.marealta.persistence.RoomRepository;
 70	import java.sql.Connection;
 71	import java.sql.SQLException;
 72	import java.time.LocalDate;
 73	import java.util.List;
 74	import java.util.function.UnaryOperator;
 75	
 76	public final class ReservationService {
 77	    public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
 78	                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
 79	    }
 80	
 81	    private final Database database;
 82	    private final RoomRepository rooms;
 83	    private final ReservationRepository reservations;
 84	    private final MessageSink messages;
 85	
 86	    public ReservationService(Database database, RoomRepository rooms, ReservationRepository reservations,
 87	                              MessageSink messages) {
 88	        this.database = database;
 89	        this.rooms = rooms;
 90	        this.reservations = reservations;
 91	        this.messages = messages;
 92	    }
 93	
 94	    public List<Room> rooms() {
 95	        return database.inTransaction(rooms::findAll);
 96	    }
 97	
 98	    public Reservation create(NewReservation request) {
 99	        return database.inTransaction(c -> {
100	            Room room = rooms.findForUpdate(c, request.roomNumber()).orElseThrow(
101	                    () -> new DomainException(ErrorCode.ROOM_NOT_FOUND, "Room not found: " + request.roomNumber()));
102	            if (request.guests() > room.capacity()) {
103	                throw new DomainException(ErrorCode.CAPACITY_EXCEEDED,
104	                        "Room " + room.number() + " holds up to " + room.capacity() + " guests");
105	            }
106	            if (reservations.hasOverlap(c, room.number(), request.checkIn(), request.checkOut())) {
107	                throw new DomainException(ErrorCode.ROOM_UNAVAILABLE,
108	                        "Room " + room.number() + " is already reserved in some of these nights");
109	            }
110	            Quote quote = Quote.of(room, request.checkIn(), request.checkOut(), request.ratePlan());
111	            return reservations.insert(c, new Reservation(0, room.number(), request.guestName(),
112	                    request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(),
113	                    request.guests(), request.ratePlan(), quote.nights(), quote.subtotal(), quote.discount(),
114	                    quote.total(), ReservationStatus.PENDING, Money.ZERO, null));
115	        });
116	    }
117	
118	    public Reservation get(long id) {
119	        return database.inTransaction(c -> load(c, id));
120	    }
121	
122	    public Reservation confirm(long id) {
123	        Reservation confirmed = transition(id, Reservation::confirmed);
124	        Receipt receipt = receiptOf(confirmed);
125	        messages.deliver(Message.email(confirmed.guestEmail(), "Reserva confirmada - Pousada Maré Alta",
126	                "Olá, " + confirmed.guestName() + "!\n\n"
127	                        + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
128	                        + receipt.toText() + "\n\n"
129	                        + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
130	                        + "Até breve!"));
131	        return confirmed;
132	    }
133	
134	    public Reservation cancel(long id) {
135	        return transition(id, Reservation::cancelled);
136	    }
137	
138	    public Reservation checkIn(long id) {
139	        return transition(id, Reservation::checkedIn);
140	    }
141	
142	    public Receipt checkOut(long id) {
143	        return receiptOf(transition(id, Reservation::checkedOut));
144	    }
145	
146	    /** The second copy of the receipt: only for paid reservations. */
147	    public Receipt document(long id) {
148	        Reservation reservation = get(id);
149	        if (!reservation.status().isPaid()) {
150	            throw new DomainException(ErrorCode.OPERATION_NOT_ALLOWED,
151	                    "No receipt for a reservation in status " + reservation.status());
152	        }
153	        return receiptOf(reservation);
154	    }
155	
156	    private Receipt receiptOf(Reservation reservation) {
157	        Room room = database.inTransaction(c -> rooms.find(c, reservation.roomNumber()).orElseThrow());
158	        return Receipt.of(reservation, room);
159	    }
160	
161	    /** The sequence shared by every operation: lock, change, save. The change says what is its own. */
162	    private Reservation transition(long id, UnaryOperator<Reservation> change) {
163	        return database.inTransaction(c -> {
164	            Reservation changed = change.apply(loadForUpdate(c, id));
165	            reservations.updateState(c, changed);
166	            return changed;
167	        });
168	    }
169	
170	    private Reservation load(Connection c, long id) throws SQLException {
171	        return reservations.find(c, id).orElseThrow(() -> notFound(id));
172	    }
173	
174	    private Reservation loadForUpdate(Connection c, long id) throws SQLException {
175	        return reservations.findForUpdate(c, id).orElseThrow(() -> notFound(id));
176	    }
177	
178	    private static DomainException notFound(long id) {
179	        return new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "Reservation not found: " + id);
180	    }
181	}
182	package br.com.marealta;
183	
184	import br.com.marealta.domain.Money;
185	import br.com.marealta.domain.Reservation;
186	import br.com.marealta.domain.Room;
187	import br.com.marealta.persistence.Database;
188	import br.com.marealta.persistence.ReservationRepository;
189	import br.com.marealta.persistence.RoomRepository;
190	import java.math.BigDecimal;
191	import java.time.LocalDate;
192	import java.time.YearMonth;
193	import java.util.List;
194	import java.util.Map;
195	import java.util.function.Function;
196	import java.util.stream.Collectors;
197	
198	public final class Reports {
199	    private final Database database;
200	    private final RoomRepository rooms;
201	    private final ReservationRepository reservations;
202	
203	    public Reports(Database database, RoomRepository rooms, ReservationRepository reservations) {
204	        this.database = database;
205	        this.rooms = rooms;
206	        this.reservations = reservations;
207	    }
208	
209	    public String occupancy(LocalDate night) {
210	        return database.inTransaction(c -> {
211	            List<Room> allRooms = rooms.findAll(c);
212	            Map<Integer, Room> byNumber = allRooms.stream().collect(Collectors.toMap(Room::number, Function.identity()));
213	            List<Reservation> occupying = reservations.paidOccupying(c, night);
214	            StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
215	            for (Reservation r : occupying) {
216	                csv.append(r.roomNumber()).append(',').append(byNumber.get(r.roomNumber()).type()).append(',')
217	                        .append(r.id()).append(',').append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
218	            }
219	            long occupiedRooms = occupying.stream().map(Reservation::roomNumber).distinct().count();
220	            return csv.append("total,").append(occupiedRooms).append('/').append(allRooms.size()).append('\n')
221	                    .toString();
222	        });
223	    }
224	
225	    public String revenue(YearMonth month) {
226	        return database.inTransaction(c -> {
227	            List<Reservation> list = reservations.withRevenueStartingBetween(c, month.atDay(1),
228	                    month.plusMonths(1).atDay(1));
229	            StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
230	            BigDecimal total = Money.ZERO;
231	            for (Reservation r : list) {
232	                csv.append(r.id()).append(',').append(r.roomNumber()).append(',').append(r.checkIn()).append(',')
233	                        .append(r.checkOut()).append(',').append(r.status()).append(',')
234	                        .append(r.revenue().toPlainString()).append('\n');
235	                total = total.add(r.revenue());
236	            }
237	            return csv.append("total,").append(Money.round(total).toPlainString()).append('\n').toString();
238	        });
239	    }
240	}

