  1	package br.com.marealta.web;
  2	
  3	import br.com.marealta.Reports;
  4	import br.com.marealta.ReservationService;
  5	import br.com.marealta.ReservationService.NewReservation;
  6	import br.com.marealta.domain.DomainException;
  7	import br.com.marealta.domain.ErrorCode;
  8	import br.com.marealta.domain.RatePlan;
  9	import br.com.marealta.persistence.StoredMessages;
 10	import com.fasterxml.jackson.databind.JsonNode;
 11	import com.fasterxml.jackson.databind.ObjectMapper;
 12	import io.javalin.Javalin;
 13	import io.javalin.http.Context;
 14	import java.io.IOException;
 15	import java.time.LocalDate;
 16	import java.time.YearMonth;
 17	import java.time.format.DateTimeParseException;
 18	import java.util.Map;
 19	
 20	public final class Routes {
 21	    private static final String CSV = "text/csv; charset=utf-8";
 22	
 23	    private final ReservationService service;
 24	    private final StoredMessages messages;
 25	    private final Reports reports;
 26	    private final ObjectMapper mapper;
 27	
 28	    public Routes(ReservationService service, StoredMessages messages, Reports reports, ObjectMapper mapper) {
 29	        this.service = service;
 30	        this.messages = messages;
 31	        this.reports = reports;
 32	        this.mapper = mapper;
 33	    }
 34	
 35	    public void register(Javalin app) {
 36	        app.exception(DomainException.class, (e, ctx) -> error(ctx, e.code().httpStatus(), e.code().name(), e.getMessage()));
 37	        app.exception(Exception.class, (e, ctx) -> {
 38	            e.printStackTrace();
 39	            error(ctx, 500, "INTERNAL_ERROR", "Unexpected error");
 40	        });
 41	
 42	        app.get("/rooms", ctx -> ctx.json(service.rooms()));
 43	        app.post("/reservations", ctx -> ctx.status(201).json(service.create(parseNewReservation(ctx))));
 44	        app.get("/reservations/{id}", ctx -> ctx.json(service.get(id(ctx))));
 45	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(service.confirm(id(ctx))));
 46	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(service.cancel(id(ctx))));
 47	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(service.checkIn(id(ctx))));
 48	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(service.checkOut(id(ctx))));
 49	        app.get("/reservations/{id}/document", ctx -> ctx.json(service.document(id(ctx))));
 50	        app.get("/messages", ctx -> ctx.json(messages.list()));
 51	        app.get("/reports/occupancy", ctx -> ctx.contentType(CSV).result(
 52	                reports.occupancy(parseDate(ctx.queryParam("date"), "date"))));
 53	        app.get("/reports/revenue", ctx -> ctx.contentType(CSV).result(
 54	                reports.revenue(parseMonth(ctx.queryParam("month")))));
 55	    }
 56	
 57	    private void error(Context ctx, int status, String code, String message) {
