  1	package br.com.marealta.persistence;
  2	
  3	import java.sql.Connection;
  4	import java.sql.SQLException;
  5	import java.sql.Statement;
  6	import org.postgresql.ds.PGSimpleDataSource;
  7	
  8	public final class Database {
  9	    @FunctionalInterface
 10	    public interface Work<T> {
 11	        T run(Connection connection) throws SQLException;
 12	    }
 13	
 14	    private final PGSimpleDataSource dataSource = new PGSimpleDataSource();
 15	
 16	    public Database(String url, String user, String password) {
 17	        dataSource.setUrl(url);
 18	        dataSource.setUser(user);
 19	        dataSource.setPassword(password);
 20	    }
 21	
 22	    /** Runs the work in one transaction: commits if it finishes, rolls back if it throws. */
 23	    public <T> T inTransaction(Work<T> work) {
 24	        try (Connection connection = dataSource.getConnection()) {
 25	            connection.setAutoCommit(false);
 26	            try {
 27	                T result = work.run(connection);
 28	                connection.commit();
 29	                return result;
 30	            } catch (SQLException | RuntimeException e) {
 31	                connection.rollback();
 32	                throw e;
 33	            }
 34	        } catch (SQLException e) {
 35	            throw new IllegalStateException("Database error: " + e.getMessage(), e);
 36	        }
 37	    }
 38	
 39	    /** Creates what the system needs in an empty database, waiting for the database to come up. */
 40	    public void initialize() {
 41	        SQLException last = null;
 42	        for (int attempt = 0; attempt < 30; attempt++) {
 43	            try {
 44	                createSchema();
 45	                return;
 46	            } catch (SQLException e) {
 47	                last = e;
 48	                try {
 49	                    Thread.sleep(2000);
 50	                } catch (InterruptedException interrupted) {
 51	                    Thread.currentThread().interrupt();
 52	                    break;
 53	                }
 54	            }
 55	        }
 56	        throw new IllegalStateException("Could not prepare the database", last);
 57	    }
 58	
 59	    private void createSchema() throws SQLException {
 60	        try (Connection connection = dataSource.getConnection(); Statement st = connection.createStatement()) {
 61	            st.execute("SELECT pg_advisory_lock(7070)");
 62	            try {
 63	                st.execute("""
 64	                        CREATE TABLE IF NOT EXISTS rooms (
 65	                          number INT PRIMARY KEY,
 66	                          type VARCHAR(20) NOT NULL,
 67	                          capacity INT NOT NULL,
 68	                          nightly_rate NUMERIC(12,2) NOT NULL)""");
 69	                st.execute("""
 70	                        CREATE TABLE IF NOT EXISTS reservations (
 71	                          id BIGSERIAL PRIMARY KEY,
 72	                          room_number INT NOT NULL REFERENCES rooms(number),
 73	                          guest_name TEXT NOT NULL,
 74	                          guest_email TEXT NOT NULL,
 75	                          guest_cpf TEXT NOT NULL,
 76	                          check_in DATE NOT NULL,
 77	                          check_out DATE NOT NULL,
 78	                          guests INT NOT NULL,
 79	                          rate_plan VARCHAR(20) NOT NULL,
 80	                          nights INT NOT NULL,
 81	                          subtotal NUMERIC(12,2) NOT NULL,
 82	                          discount NUMERIC(12,2) NOT NULL,
 83	                          total NUMERIC(12,2) NOT NULL,
 84	                          status VARCHAR(20) NOT NULL,
 85	                          amount_paid NUMERIC(12,2) NOT NULL,
 86	                          refund NUMERIC(12,2))""");
 87	                st.execute("""
 88	                        CREATE TABLE IF NOT EXISTS messages (
 89	                          id BIGSERIAL PRIMARY KEY,
 90	                          channel VARCHAR(20) NOT NULL,
 91	                          recipient TEXT NOT NULL,
 92	                          subject TEXT NOT NULL,
 93	                          body TEXT NOT NULL,
 94	                          status VARCHAR(20) NOT NULL)""");
 95	                st.execute("""
 96	                        INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
 97	                          (101, 'STANDARD', 2, 249.90),
 98	                          (102, 'STANDARD', 2, 249.90),
 99	                          (201, 'DELUXE', 3, 389.90),
100	                          (202, 'DELUXE', 3, 389.90),
101	                          (301, 'SUITE', 4, 579.90)
102	                        ON CONFLICT (number) DO NOTHING""");
103	            } finally {
104	                st.execute("SELECT pg_advisory_unlock(7070)");
105	            }
106	        }
107	    }
108	}
