125	public final class ReservationRepository {
126	    private static final String PAID = "status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')";
127	
128	    public Reservation insert(Connection c, Reservation r) throws SQLException {
129	        String sql = """
130	                INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
131	                  guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund)
132	                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""";
133	        try (PreparedStatement ps = c.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
134	            ps.setInt(1, r.roomNumber());
135	            ps.setString(2, r.guestName());
136	            ps.setString(3, r.guestEmail());
137	            ps.setString(4, r.guestCpf());
138	            ps.setDate(5, Date.valueOf(r.checkIn()));
139	            ps.setDate(6, Date.valueOf(r.checkOut()));
140	            ps.setInt(7, r.guests());
141	            ps.setString(8, r.ratePlan().name());
142	            ps.setInt(9, r.nights());
143	            ps.setBigDecimal(10, r.subtotal());
144	            ps.setBigDecimal(11, r.discount());
145	            ps.setBigDecimal(12, r.total());
146	            ps.setString(13, r.status().name());
147	            ps.setBigDecimal(14, r.amountPaid());
148	            ps.setBigDecimal(15, r.refund());
149	            ps.executeUpdate();
150	            try (ResultSet keys = ps.getGeneratedKeys()) {
151	                keys.next();
152	                return find(c, keys.getLong(1)).orElseThrow();
153	            }
154	        }
155	    }
156	
157	    public void updateState(Connection c, Reservation r) throws SQLException {
158	        try (PreparedStatement ps = c.prepareStatement(
159	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
160	            ps.setString(1, r.status().name());
161	            ps.setBigDecimal(2, r.amountPaid());
162	            ps.setBigDecimal(3, r.refund());
163	            ps.setLong(4, r.id());
164	            ps.executeUpdate();
165	        }
166	    }
167	
168	    public Optional<Reservation> find(Connection c, long id) throws SQLException {
169	        return queryOne(c, "SELECT * FROM reservations WHERE id = ?", id);
170	    }
171	
172	    public Optional<Reservation> findForUpdate(Connection c, long id) throws SQLException {
173	        return queryOne(c, "SELECT * FROM reservations WHERE id = ? FOR UPDATE", id);
174	    }
175	
176	    /** True if a non-cancelled reservation of the room takes any night in [checkIn, checkOut). */
177	    public boolean hasOverlap(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut)
178	            throws SQLException {
179	        String sql = """
180	                SELECT 1 FROM reservations
181	                WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?
182	                LIMIT 1""";
183	        try (PreparedStatement ps = c.prepareStatement(sql)) {
184	            ps.setInt(1, roomNumber);
185	            ps.setDate(2, Date.valueOf(checkOut));
186	            ps.setDate(3, Date.valueOf(checkIn));
187	            try (ResultSet rs = ps.executeQuery()) {
188	                return rs.next();
189	            }
190	        }
191	    }
192	
193	    /** Paid reservations that occupy a room on the given night. */
194	    public List<Reservation> paidOccupying(Connection c, LocalDate night) throws SQLException {
195	        return queryList(c, "SELECT * FROM reservations WHERE " + PAID
196	                + " AND check_in <= ? AND check_out > ? ORDER BY room_number, id",
197	                Date.valueOf(night), Date.valueOf(night));
198	    }
199	
200	    /** Reservations with check-in in [from, to) that left money with the hotel. */
201	    public List<Reservation> withRevenueStartingBetween(Connection c, LocalDate from, LocalDate to)
202	            throws SQLException {
203	        return queryList(c, "SELECT * FROM reservations WHERE check_in >= ? AND check_in < ?"
204	                + " AND amount_paid - COALESCE(refund, 0) > 0 ORDER BY check_in, id",
205	                Date.valueOf(from), Date.valueOf(to));
206	    }
207	
208	    private Optional<Reservation> queryOne(Connection c, String sql, long id) throws SQLException {
209	        try (PreparedStatement ps = c.prepareStatement(sql)) {
210	            ps.setLong(1, id);
211	            try (ResultSet rs = ps.executeQuery()) {
212	                return rs.next() ? Optional.of(read(rs)) : Optional.empty();
213	            }
214	        }
215	    }
216	
217	    private List<Reservation> queryList(Connection c, String sql, Date... params) throws SQLException {
218	        try (PreparedStatement ps = c.prepareStatement(sql)) {
219	            for (int i = 0; i < params.length; i++) {
220	                ps.setDate(i + 1, params[i]);
221	            }
222	            try (ResultSet rs = ps.executeQuery()) {
223	                List<Reservation> list = new ArrayList<>();
224	                while (rs.next()) {
225	                    list.add(read(rs));
226	                }
227	                return list;
228	            }
229	        }
230	    }
231	
232	    private Reservation read(ResultSet rs) throws SQLException {
233	        return new Reservation(
234	                rs.getLong("id"),
235	                rs.getInt("room_number"),
236	                rs.getString("guest_name"),
237	                rs.getString("guest_email"),
238	                rs.getString("guest_cpf"),
239	                rs.getDate("check_in").toLocalDate(),
240	                rs.getDate("check_out").toLocalDate(),
241	                rs.getInt("guests"),
242	                RatePlan.valueOf(rs.getString("rate_plan")),
243	                rs.getInt("nights"),
244	                rs.getBigDecimal("subtotal"),
245	                rs.getBigDecimal("discount"),
246	                rs.getBigDecimal("total"),
247	                ReservationStatus.valueOf(rs.getString("status")),
248	                rs.getBigDecimal("amount_paid"),
249	                rs.getBigDecimal("refund"));
250	    }
251	}
