320	    @Override
321	    public void deliver(Message m) {
322	        database.inTransaction(c -> {
323	            try (PreparedStatement ps = c.prepareStatement(
324	                    "INSERT INTO messages (channel, recipient, subject, body, status) VALUES (?, ?, ?, ?, ?)")) {
325	                ps.setString(1, m.channel().name());
326	                ps.setString(2, m.to());
327	                ps.setString(3, m.subject());
328	                ps.setString(4, m.body());
329	                ps.setString(5, m.status().name());
330	                ps.executeUpdate();
331	                return null;
332	            }
333	        });
334	    }
335	
336	    public List<Message> list() {
337	        return database.inTransaction(c -> {
338	            try (PreparedStatement ps = c.prepareStatement("SELECT * FROM messages ORDER BY id");
339	                 ResultSet rs = ps.executeQuery()) {
340	                List<Message> messages = new ArrayList<>();
341	                while (rs.next()) {
342	                    messages.add(new Message(rs.getLong("id"), Channel.valueOf(rs.getString("channel")),
343	                            rs.getString("recipient"), rs.getString("subject"), rs.getString("body"),
344	                            MessageStatus.valueOf(rs.getString("status"))));
345	                }
346	                return messages;
347	            }
348	        });
349	    }
