 37	    }
 38	
 39	    /** Creates what the system needs in an empty database, waiting for the database to come up. */
 40	    public void initialize() {
 41	        SQLException last = null;
 42	        for (int attempt = 0; attempt < 30; attempt++) {
 43	            try {
 44	                createSchema();
 45	                return;
 46	            } catch (SQLException e) {
 47	                last = e;
 48	                try {
 49	                    Thread.sleep(2000);
 50	                } catch (InterruptedException interrupted) {
 51	                    Thread.currentThread().interrupt();
 52	                    break;
 53	                }
 54	            }
 55	        }
 56	        throw new IllegalStateException("Could not prepare the database", last);
 57	    }
 58	
 59	    private void createSchema() throws SQLException {
 60	        try (Connection connection = dataSource.getConnection(); Statement st = connection.createStatement()) {
 61	            st.execute("SELECT pg_advisory_lock(7070)");
 62	            try {
 63	                st.execute("""
 64	                        CREATE TABLE IF NOT EXISTS rooms (
 65	                          number INT PRIMARY KEY,
 66	                          type VARCHAR(20) NOT NULL,
 67	                          capacity INT NOT NULL,
 68	                          nightly_rate NUMERIC(12,2) NOT NULL)""");
 69	                st.execute("""
 70	                        CREATE TABLE IF NOT EXISTS reservations (
 71	                          id BIGSERIAL PRIMARY KEY,
 72	                          room_number INT NOT NULL REFERENCES rooms(number),
 73	                          guest_name TEXT NOT NULL,
 74	                          guest_email TEXT NOT NULL,
