 80	                          nights INT NOT NULL,
 81	                          subtotal NUMERIC(12,2) NOT NULL,
 82	                          discount NUMERIC(12,2) NOT NULL,
 83	                          total NUMERIC(12,2) NOT NULL,
 84	                          status VARCHAR(20) NOT NULL,
 85	                          amount_paid NUMERIC(12,2) NOT NULL,
 86	                          refund NUMERIC(12,2))""");
 87	                st.execute("""
 88	                        CREATE TABLE IF NOT EXISTS messages (
 89	                          id BIGSERIAL PRIMARY KEY,
 90	                          channel VARCHAR(20) NOT NULL,
 91	                          recipient TEXT NOT NULL,
 92	                          subject TEXT NOT NULL,
 93	                          body TEXT NOT NULL,
 94	                          status VARCHAR(20) NOT NULL)""");
 95	                st.execute("""
 96	                        INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
 97	                          (101, 'STANDARD', 2, 249.90),
 98	                          (102, 'STANDARD', 2, 249.90),
