  3	/** Blocks messages whose address is not valid: one @, something before it, a dotted name after it. */
  4	public final class AddressValidation implements MessageSink {
  5	    private final MessageSink next;
  6	    private final MessageSink blocked;
  7	
  8	    public AddressValidation(MessageSink next, MessageSink blocked) {
  9	        this.next = next;
 10	        this.blocked = blocked;
 11	    }
 12	
 13	    @Override
 14	    public void deliver(Message message) {
 15	        if (isValid(message.to())) {
 16	            next.deliver(message);
 17	        } else {
 18	            blocked.deliver(message.blocked());
 19	        }
 20	    }
 21	
 22	    static boolean isValid(String address) {
 23	        if (address == null) {
 24	            return false;
 25	        }
 26	        int at = address.indexOf('@');
 27	        if (at <= 0 || at != address.lastIndexOf('@')) {
 28	            return false;
 29	        }
 30	        String domain = address.substring(at + 1);
 31	        int dot = domain.indexOf('.');
 32	        return dot > 0 && !domain.endsWith(".") && domain.chars().noneMatch(Character::isWhitespace);
 33	    }
 34	}
