102	/** Assembles the rules that apply in the current mode around the sink that stores messages. */
103	public final class MessagePipeline {
104	    private MessagePipeline() {
105	    }
106	
107	    /** The first rule of the list is the outermost one. */
108	    public static MessageSink assemble(MessageSink store, List<ScopedRule> rules, boolean testMode) {
109	        MessageSink head = store;
110	        for (int i = rules.size() - 1; i >= 0; i--) {
111	            ScopedRule scoped = rules.get(i);
112	            if (scoped.scope().appliesTo(testMode)) {
113	                head = scoped.rule().wrap(head, store);
114	            }
115	        }
116	        MessageSink first = head;
117	        Object lock = new Object();
118	        // one message at a time, so a message and its copy stay together in the list
119	        return message -> {
120	            synchronized (lock) {
121	                first.deliver(message);
122	            }
123	        };
124	    }
125	}
