222	import br.com.marealta.messaging.*;
223	import java.util.ArrayList;
224	import java.util.List;
225	import org.junit.jupiter.api.Test;
226	
227	class MessagePipelineTest {
228	    private final List<Message> store = new ArrayList<>();
229	
230	    private MessageSink pipeline(boolean testMode, List<ScopedRule> rules) {
231	        return MessagePipeline.assemble(store::add, rules, testMode);
232	    }
233	
234	    @Test
235	    void liveModeSendsAndArchives() {
236	        pipeline(false, Installation.mareAlta()).deliver(Message.email("ana@gmail.com", "Oi", "Texto"));
237	        assertEquals(2, store.size());
238	        assertEquals("ana@gmail.com", store.get(0).to());
239	        assertEquals("arquivo@pousadamarealta.com.br", store.get(1).to());
240	        assertEquals("[Cópia] Oi", store.get(1).subject());
241	        assertEquals("Texto", store.get(1).body());
242	    }
243	
244	    @Test
245	    void testModeRedirectsWithoutArchive() {
246	        pipeline(true, Installation.mareAlta()).deliver(Message.email("ana@gmail.com", "Oi", "Texto"));
247	        assertEquals(1, store.size());
248	        assertEquals("testes@pousadamarealta.com.br", store.get(0).to());
249	        assertEquals("[TESTE] Oi", store.get(0).subject());
250	        assertEquals("Destinatário original: ana@gmail.com\nTexto", store.get(0).body());
251	        assertEquals(MessageStatus.SENT, store.get(0).status());
252	    }
253	
254	    @Test
255	    void invalidAddressIsBlockedWithOriginalAddressInBothModes() {
256	        for (boolean testMode : new boolean[] {false, true}) {
257	            store.clear();
258	            for (String bad : List.of("ana@gmail", "ana.gmail.com", "a@@b.com", "@b.com", "a@.com", "a@b.")) {
259	                pipeline(testMode, Installation.mareAlta()).deliver(Message.email(bad, "Oi", "Texto"));
260	            }
261	            assertEquals(6, store.size());
262	            store.forEach(m -> assertEquals(MessageStatus.BLOCKED, m.status()));
263	            assertEquals("ana@gmail", store.get(0).to());
264	            assertEquals("Oi", store.get(0).subject());
265	        }
266	    }
267	
268	    @Test
269	    void anotherInstallationCanLeaveRulesOut() {
270	        List<ScopedRule> withoutArchive = List.of(Installation.mareAlta().get(0), Installation.mareAlta().get(2));
271	        pipeline(false, withoutArchive).deliver(Message.email("ana@gmail.com", "Oi", "Texto"));
272	        assertEquals(1, store.size());
273	    }
